    // Attempting to vote for deactivated "Bob" should revert
    await contract.whitelistAnonymousWallet(voter1.address);
    await expect(contract.connect(voter1).vote(1)).to.be.revertedWith(
      "AV: candidate is inactive"
    );
  })

