  const sigBytes = ethers.solidityPacked(["bytes32", "bytes32", "uint8"], [r, s, v]);
  return ethers.keccak256(ethers.solidityPacked(["uint8", "bytes", "bytes32"], [decision, sigBytes, salt]));
}
