        uint16 dstChainId,
        bytes memory payload,
        uint256 value,
        address refundAddress
    ) internal {
        bytes32 messageId = bridge.sendMessage{value: value}(dstChainId, payload, refundAddress);
        if (uint256(messageId) < 1) revert InvalidMessageId();
    }

