        );
      }

      const allCampaigns = await factory.getDeployedCampaigns();
      expect(allCampaigns.length).to.equal(3);

      // Page 1: offset 0, limit 2
      const [page1, total1] = await factory.getDeployedCampaignsPaginated(0, 2);
