let admin, beneficiary, stranger;
const ONE_DAY    = 86400;
const CLIFF      = ONE_DAY * 30;
const VESTING    = ONE_DAY * 180;
const ALLOCATION = ethers.parseEther("1000");
// beforeEach of suite "DOCVesting — Security Audit"
beforeEach(async function () {
