    function withdraw() external {
        uint256 bal = bids[msg.sender];
        require(bal > 0, "balance is zero");
        bids[msg.sender] = 0;
        payable(msg.sender).transfer(bal); // Transfer the balance to the callerc

        emit Withdraw(msg.sender, bal);
    }

