        expect(balanceAfter - balanceBefore).to.be.closeTo(ETH_AMOUNT, ethers.parseEther("0.01"));

        const deposit = await exclusiveClaim.getDeposit(depositId);
        expect(deposit.claimed).to.equal(true);
      })

