const { time } = require("@nomicfoundation/hardhat-network-helpers");
let exclusiveClaim;
let mockToken;
let depositor;
let claimant;
let other;
const ONE_HOUR = 60 * 60;
const ONE_DAY = 24 * ONE_HOUR;
const ETH_AMOUNT = ethers.parseEther("1");
