            (int256(lengthArray) - int256(offset + itemsAmount)) >= 0,
            "Offset + itemsAmount bigger than the array"
        );
        address[] memory result = new address[](itemsAmount);
        uint256 counter = 1;
        uint256 index = 0;
        for (uint256 x = offset; counter <= itemsAmount; x++) {
            result[index] = mySet.at(x);
            index++;
            counter++;
        }
        return result;
    }

