    ) ERC4626(asset_) Ownable(msg.sender) {
        require(rewardToken_ != address(0), "reward token");
        require(annualRateBps_ <= 10_000, "bps");
        rewardToken = IRewardToken(rewardToken_);
        annualRateBps = annualRateBps_;
