    function acceptJob(uint256 _jobId) external {
        JobDetail storage job = jobs[_jobId];
        require(job.isOpen, "Job already taken.");
        job.freelancer = msg.sender;
        job.isOpen = false;
        emit JobAccepted(_jobId, msg.sender);
    }
}

