// OverlayerReferral.sol (dependency), modifier OverlayerReferral.onlyTracker
modifier onlyTracker() {
        if (!allowedPointsTrackers[msg.sender] && msg.sender != address(this)) {
            revert OverlayerReferralNotAllowed();
        }
        _;
    }

