let escrow;
let client;
let freelancer;
let pm;
let other;
const ZERO_ADDRESS = ethers.ZeroAddress;
const Status = {
    Created: 0,
    InProgress: 1,
    Submitted: 2,
    Approved: 3,
    Paid: 4,
  };
let projectId;
const amount = ethers.parseEther("1");
// beforeEach of suite "MilestoneEscrow"
beforeEach(async () => {
    [client, freelancer, pm, other] = await ethers.getSigners();
