            expect(aliceValue).to.equal(30000);

            await nft.updateValuation(0, 12000);
            await nft.updateValuation(2, 25000);

            const newAliceValue = await nft.totalValueOf(alice.address);
            expect(newAliceValue).to.equal(37000);
        });
    });
});

