        vault
          .connect(pledger)
          .createPledge(witness.address, destination.address, await usdc.getAddress(), USDC(200), deadline)
      )
        .to.emit(vault, "PledgeCreated")
        .withArgs(
          (id) => ethers.isHexString(id, 32),
          pledger.address,
          witness.address,
          await usdc.getAddress(),
          USDC(200),
          deadline,
          destination.address
        );

