      await expect(
        vault
          .connect(pledger)
          .createPledge(pledger.address, destination.address, await usdc.getAddress(), USDC(1), deadline)
      ).to.be.revertedWithCustomError(vault, "WitnessIsPledger");
    });

    it("reverts on a deadline in the past", async () => {
