      const past = BigInt(await time.latest()) - 1n;
      await expect(
        vault
          .connect(pledger)
          .createPledge(witness.address, destination.address, await usdc.getAddress(), USDC(1), past)
      ).to.be.revertedWithCustomError(vault, "DeadlineInPast");
