    };
    const types = {
        Voucher: [
            { name: "channel", type: "address" },
            { name: "nonce", type: "uint256" },
            { name: "deadline", type: "uint256" },
            { name: "model", type: "string" },
            { name: "inputTokenAmount", type: "uint256" },
            { name: "maxOutputTokenAmount", type: "uint256" },
