    it("Should handle maximum risk score", async function () {
      const actionType = 1;
      const intentHash = ethers.keccak256(ethers.toUtf8Bytes("max risk"));
      const proofHash = ethers.keccak256(ethers.toUtf8Bytes("max proof"));
