        if (feeCharged > 0) {
            claimableWei[feeRecipient] += feeCharged;
        }

        gameState = GameState.Resolved;

        emit RoundResolved(address(this), currentRoundIndex, winnersCount, feeCharged, perWinnerBase);
    }

