      await auction.connect(beneficiary).collectForfeitedDeposit(dave.address);
      await expect(
        auction.connect(beneficiary).collectForfeitedDeposit(dave.address)
      ).to.be.revertedWithCustomError(auction, "NothingCommitted");
    });

