      await time.increase(60 * 60 * 24); // 1 day

      let pending = ethers.formatEther(
        await liquidity.pendingReward(0, await alice.getAddress())
      );

      let expected = (
        ((1 / (60 * 60 * 24 * 365)) * (60 * 60 * 24) * 1) /
        1
