        require(subscriptionIds.length <= maxBatchSize, "Batch size too large");

        for (uint256 i = 0; i < subscriptionIds.length; i++) {
            uint256 subscriptionId = subscriptionIds[i];
            if (subscriptionId < nextSubscriptionId) {
